CREATE FUNCTION c1_api.review_material(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;r c1_private.reviews;BEGIN s=c1_private.auth(n,q,true);SELECT * INTO r FROM c1_private.reviews WHERE ns=n AND id=(q->>'review_id')::uuid AND subject=s.subject;IF NOT FOUND THEN PERFORM c1_private.fail('NOT_FOUND');END IF;IF r.kind='publish' THEN PERFORM c1_private.owner_auth(n,s,r.payload->>'store','catalog');END IF;RETURN jsonb_build_object('kind',r.kind,'payload',r.payload,'scope',(SELECT manifest->'stores'->(r.payload->>'store') FROM c1_private.deployment WHERE ns=n));END $$;
CREATE FUNCTION c1_api.intent_retry(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;BEGIN s=c1_private.auth(n,q,true);IF q->>'action' IN('publish','list','pause','close') THEN PERFORM c1_private.owner_auth(n,s,q->>'store','catalog');ELSIF q->>'action' IN('lock','handover') THEN PERFORM c1_private.owner_auth(n,s,q->>'store','redeem');ELSIF q->>'action'='settle' THEN PERFORM c1_private.owner_auth(n,s,q->>'store','payout');ELSIF q->>'action' IN('fund','refund') AND NOT EXISTS(SELECT 1 FROM c1_private.payer_bindings WHERE ns=n AND subject=s.subject AND enabled) THEN PERFORM c1_private.fail('PAYER_REQUIRED');END IF;RETURN coalesce(c1_private.idem(n,s,q->>'action',q),'{}');END $$;
